import json
import sys
from pathlib import Path

COURSE = Path(__file__).resolve().parent
sys.path.insert(0, str(COURSE.parents[1]))
from web_author import text, tex, box, img, html, quiz, R

INK, ACCENT, BODY, RED = '#16283F', '#244B88', '#273444', '#B32938'
RULE, FILL = '#D8E0EA', '#F1F6FD'
FONT = 'Microsoft YaHei, PingFang SC, sans-serif'

def T(s,x,y,w,lines,size=38,h=100,color=BODY,b=False,**kw):
    if isinstance(lines,str): lines=[lines]
    return text(s,x,y,w,[[R(v,size,color,b,font=FONT)] for v in lines],h=h,**kw)

def header(num,title):
    return [T(0,105,40,1490,f'{num}　{title}',44,64,INK,True),
      box(0,105,118,96,6,ACCENT,ACCENT,lw=0,pad=0,decorative=True),
      box(0,105,160,1710,2,RULE,RULE,lw=0,pad=0,decorative=True)]

def hot(label,answer):
    return dict(hotspot=True,label=label,qa=[{'q':label+'？','a':answer}])

def F(s,y,f,size=48,x=140,w=1630,h=105,**kw):
    return tex(s,x,y,w,f,size=size,h=h,color=INK,**kw)

def note(s,lines,y=865,**kw):
    return T(s,140,y,1610,lines,34,h=(120 if isinstance(lines,list) else (60 if y>=930 else 85)),color=ACCENT,**kw)

def quiz_after(after_sentence, *args, **kwargs):
    """题卡使用现有完整句的结束时钟，配音文字保持原样。"""
    return {**quiz(*args, **kwargs), 'after_sentence': after_sentence}

pages=[]
def page(title,num,narration,elements,interactions=None):
    p={'id':len(pages)+1,'heading':title,'narration':narration,'elements':elements}
    if num is not None:p['elements']=header(num,title)+elements
    if interactions:p['interactions']=interactions
    pages.append(p)

